//! ↔️ Real paged transfers conserve independent work, physical backing and denied original owners.
use semio_framework_value_paged_list::PagedList;
use semio_framework_value_control_contract::{RetainedCloneGrant,RetainedCloneProgress,RetainedWorkPoll};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
struct Bank{g:RetainedCloneGrant,work:u64}
impl Bank{
 fn new(f:&serde_json::Value)->Self{let s=&f["stock"];Self{g:RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize},work:s["fuel"].as_u64().unwrap()}}
 fn grant(&self)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:self.g.maximum_items.min(1),..self.g}}
 fn post(&mut self,p:RetainedCloneProgress,work:u128,heap:(usize,usize)){assert!(p.fits(self.g));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));self.g.maximum_items=self.g.maximum_items.checked_sub(p.copied_items).unwrap();self.g.maximum_copy_bytes=self.g.maximum_copy_bytes.checked_sub(p.copied_bytes).unwrap();self.g.maximum_capacity_bytes=self.g.maximum_capacity_bytes.checked_sub(p.retained_capacity_bytes).unwrap();self.g.maximum_release_bytes=self.g.maximum_release_bytes.checked_sub(p.released_bytes).unwrap();self.work=self.work.checked_sub(u64::try_from(work).unwrap()).unwrap();}
}
fn reserve(list:&mut PagedList<u8,{usize::MAX}>,bank:&mut Bank){
 while !list.has_reserved_slot(){let q=PagedList::<u8,{usize::MAX}>::reservation_selection_work_demand();assert!(q<=bank.work);let selection=list.select_reservation(usize::MAX,q);bank.post(Default::default(),u128::from(u64::try_from(selection.work).unwrap()),(0,0));let selected=selection.result.unwrap().unwrap();let q=selected.reserve_work_demand();assert!(q<=bank.work);let g=bank.grant();let mut actual=None;let(result,h)=observe(||list.reserve_selected(&selected,g,q,&mut actual));let p=result.unwrap();assert_eq!(actual.unwrap_or(0),p.allocated_bytes);bank.post(RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes},u128::from(p.work),h);if actual.is_some(){let p=RetainedCloneProgress{copied_items:1,copied_bytes:std::mem::size_of_val(&actual),..Default::default()};assert!(p.fits(bank.grant())&&bank.work>=1);actual.take();bank.post(p,1,(0,0));}assert!(actual.is_none());}
}
#[test]
fn original_paged_transfers_follow_actual_radix_work_and_retire_every_backing(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../../🎟️reservation/↔️transfer/🔣️.json")).unwrap();
 for case in f["cases"].as_array().unwrap(){let mut bank=Bank::new(&f);let mut effect_bank=EffectBank::new(Wallet::from_profile(&f["stock"]));let mut list=PagedList::<u8,{usize::MAX}>::new();let mut oracle=std::collections::VecDeque::new();
  for index in 0..case["length"].as_u64().unwrap(){reserve(&mut list,&mut bank);let mut donor=Some(index as u8);let q=list.push_reserved_source_work_demand().unwrap();assert!(q<=bank.work);let g=bank.grant();let(turn,h)=observe(||list.push_reserved_source_step(&mut donor,q,g));let p=turn.result.unwrap().progress();assert_eq!(turn.work,u128::from(q));bank.post(p,u128::from(q),h);assert!(donor.is_none());oracle.push_back(index as u8);}
  reserve(&mut list,&mut bank);let q=list.push_reserved_source_work_demand().unwrap();assert_eq!(q,case["appendWork"].as_u64().unwrap());let len=list.len();let mut donor=Some(f["value"].as_u64().unwrap()as u8);let g=bank.grant();
  for maximum in[0,1,q-1]{let(turn,h)=observe(||list.push_reserved_source_step(&mut donor,maximum,g));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(list.len(),len);assert_eq!(donor,Some(f["value"].as_u64().unwrap()as u8));}
  let(turn,h)=observe(||list.push_reserved_source_step(&mut donor,q,g));let p=turn.result.unwrap().progress();assert_eq!(turn.work,u128::from(q));bank.post(p,u128::from(q),h);assert!(donor.is_none());oracle.push_back(f["value"].as_u64().unwrap()as u8);
  while !list.is_empty(){let q=list.pop_source_work_demand().unwrap();assert!(q<=bank.work);let len=list.len();let mut occupied=Some(99);let g=bank.grant();let((poll,actual),h)=observe(||effect_bank.run(g,q,|effect|RetainedWorkPoll::Complete(list.pop_source_step(&mut occupied,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("tail transfer must settle")};assert!(turn.result.is_err());assert_eq!(turn.work,0);assert_eq!(actual,None);assert_eq!(h,(0,0));assert_eq!(occupied,Some(99));assert_eq!(list.len(),len);let mut target=None;for maximum in[0,1,q-1]{let((poll,actual),h)=observe(||effect_bank.run(g,maximum,|effect|RetainedWorkPoll::Complete(list.pop_source_step(&mut target,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("tail transfer must settle")};assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(actual,None);assert_eq!(h,(0,0));assert!(target.is_none());assert_eq!(list.len(),len);}let((poll,actual),h)=observe(||effect_bank.run(g,q,|effect|RetainedWorkPoll::Complete(list.pop_source_step(&mut target,effect))));let RetainedWorkPoll::Complete(turn)=poll else{panic!("tail transfer must settle")};let p=turn.result.unwrap().progress();assert_eq!(turn.work,u128::from(q));assert_eq!(actual,None);assert_eq!(effect_bank.take_admitted(),Some(true));effect_bank.post(p,g,h);bank.post(p,u128::from(q),h);assert_eq!(target,oracle.pop_back());}
  while !list.terminal_is_empty(){let q=PagedList::<u8,{usize::MAX}>::release_selection_work_demand();assert!(q<=bank.work);let selection=list.select_release(q);bank.post(Default::default(),u128::from(u64::try_from(selection.work).unwrap()),(0,0));let selected=selection.result.unwrap().unwrap();let q=selected.release_work_demand();assert!(q<=bank.work);let g=bank.grant();let(turn,h)=observe(||list.release_selected(&selected,g,q));let p=turn.result.unwrap();assert!(turn.work<=u128::from(q));bank.post(RetainedCloneProgress{copied_items:usize::from(p.progressed),copied_bytes:p.placed_bytes,retained_capacity_bytes:p.allocated_bytes,released_bytes:p.released_allocation_bytes},u128::from(u64::try_from(turn.work).unwrap()),h);}
  assert!(oracle.is_empty());assert_eq!(bank.g.maximum_capacity_bytes,bank.g.maximum_release_bytes);assert_eq!(observe(||drop(list)).1,(0,0));
 }
}
